#[test]
fn window_misc() {
    check(&[
        (r"@BK8 'welch' FFTWINDOW BUCKETSPAN", Ok(r"[10]")),
        (r"@BK8 'welch' FFTWINDOW LASTBUCKET", Ok(r"[70]")),
        (r"@BK8 'welch' FFTWINDOW BUCKETCOUNT", Ok(r"[8]")),
        (r"@R8 'welch' FFTWINDOW NAME", Ok(r"[null]")),
        (r"@R8 'welch' FFTWINDOW LABELS", Ok(r"[{}]")),
        (r"@R8 'welch' FFTWINDOW ATTRIBUTES", Ok(r"[{}]")),
        (r"@R8 'welch' FFTWINDOW TYPEOF", Ok(r#"["GTS"]"#)),
        (r"@L8 'welch' FFTWINDOW TYPEOF", Ok(r#"["GTS"]"#)),
        (
            r"[ @R8 @R16 @L4 ] 'welch' FFTWINDOW",
            Ok(
                r#"[[{"c":"","l":{},"a":{},"la":0,"v":[[0,-3.133],[10,-2.311428571428572],[20,-0.6578571428571428],[30,0.48542857142857143],[40,0.029571428571428568],[50,-0.738],[60,-1.7857142857142858],[70,4.528]]},{"c":"","l":{},"a":{},"la":0,"v":[[0,-4.966],[10,3.9468000000000005],[20,-2.641466666666666],[30,-0.6192],[40,0.5525333333333333],[50,0.7213333333333334],[60,-0.35000000000000003],[70,0.0288],[80,0.12393333333333333],[90,0.32360000000000005],[100,-1.2233333333333332],[110,1.2497333333333334],[120,2.8943999999999996],[130,3.4422666666666664],[140,0.9819333333333333],[150,-4.557]]},{"c":"","l":{},"a":{},"la":0,"v":[[0,-3.0],[10,0.3333333333333333],[20,1.3333333333333333],[30,1.0]]}]]"#,
            ),
        ),
        (r"[ ] 'welch' FFTWINDOW", Ok(r"[[]]")),
        (
            r"[ @R8 ] 'welch' FFTWINDOW",
            Ok(
                r#"[[{"c":"","l":{},"a":{},"la":0,"v":[[0,-3.133],[10,-2.311428571428572],[20,-0.6578571428571428],[30,0.48542857142857143],[40,0.029571428571428568],[50,-0.738],[60,-1.7857142857142858],[70,4.528]]}]]"#,
            ),
        ),
        (
            r"@R8 'rectangular' FFTWINDOW @R8 == ",
            Ok(
                r#"[{"c":"","l":{},"a":{},"la":0,"v":[[0,3.133],[10,3.236],[20,1.535],[30,-3.398],[40,0.207],[50,-1.722],[60,-2.5],[70,4.528]]}]"#,
            ),
        ),
        (
            r"@R8 'WELCH' FFTWINDOW",
            Ok(
                r#"[{"c":"","l":{},"a":{},"la":0,"v":[[0,-3.133],[10,-2.311428571428572],[20,-0.6578571428571428],[30,0.48542857142857143],[40,0.029571428571428568],[50,-0.738],[60,-1.7857142857142858],[70,4.528]]}]"#,
            ),
        ),
        (
            r"@R8 'Parzen' FFTWINDOW",
            Ok(
                r#"[{"c":"","l":{},"a":{},"la":0,"v":[[0,3.133],[10,2.3258750000000004],[20,0.38375],[30,-0.1061875],[40,0.0],[50,0.0538125],[60,0.625],[70,-3.8204999999999996]]}]"#,
            ),
        ),
        (r"@R8 'welch' FFTWINDOW SIZE", Ok(r"[8]")),
        (r"@LOC8 'welch' FFTWINDOW SIZE", Ok(r"[8]")),
    ]);
}

#[test]
fn window_errors() {
    check(&[
        (
            r"@R8 'foo' FFTWINDOW",
            Err(r"FFTWINDOW given an unknown windowing function 'foo'."),
        ),
        (
            r"@R8 '' FFTWINDOW",
            Err(r"FFTWINDOW given an unknown windowing function ''."),
        ),
        (
            r"@R8 3 FFTWINDOW",
            Err(r"FFTWINDOW expects a STRING algorithm name."),
        ),
        (
            r"@R8 NULL FFTWINDOW",
            Err(r"FFTWINDOW expects a STRING algorithm name."),
        ),
        (
            r"@R8 FFTWINDOW",
            Err(r"FFTWINDOW expects a STRING algorithm name."),
        ),
        (r"FFTWINDOW", Err(r"Empty stack.")),
        (r"'hann' FFTWINDOW", Err(r"Empty stack.")),
        (
            r"NEWGTS 'hann' FFTWINDOW",
            Err(r"FFTWINDOW expects numeric Geo Time Series. {} is not numeric."),
        ),
        (
            r"NEWGTS 'foo' FFTWINDOW",
            Err(r"FFTWINDOW expects numeric Geo Time Series. {} is not numeric."),
        ),
        (
            r"@E8 'hann' FFTWINDOW",
            Err(r"FFTWINDOW expects numeric Geo Time Series. x{l=v} is not numeric."),
        ),
        (
            r"@S8 'hann' FFTWINDOW",
            Err(r"FFTWINDOW expects numeric Geo Time Series. x{l=v} is not numeric."),
        ),
        (
            r"@B8 'hann' FFTWINDOW",
            Err(r"FFTWINDOW expects numeric Geo Time Series. x{l=v} is not numeric."),
        ),
        (
            r"@S8 'foo' FFTWINDOW",
            Err(r"FFTWINDOW expects numeric Geo Time Series. x{l=v} is not numeric."),
        ),
        (
            r"1 'hann' FFTWINDOW",
            Err(r"FFTWINDOW can only operate on Geo Time Series instances."),
        ),
        (
            r"'a' 'hann' FFTWINDOW",
            Err(r"FFTWINDOW can only operate on Geo Time Series instances."),
        ),
        (
            r"[ @R8 @S8 ] 'hann' FFTWINDOW",
            Err(r"FFTWINDOW expects numeric Geo Time Series. x{l=v} is not numeric."),
        ),
        (
            r"[ @R8 1 ] 'hann' FFTWINDOW",
            Err(r"FFTWINDOW can only operate on Geo Time Series instances."),
        ),
        (
            r"[ @R8 NEWGTS ] 'hann' FFTWINDOW",
            Err(r"FFTWINDOW expects numeric Geo Time Series. {} is not numeric."),
        ),
        (
            r"[ 1 ] 'hann' FFTWINDOW",
            Err(r"FFTWINDOW can only operate on Geo Time Series instances."),
        ),
        (
            r"{ 'a' @R8 } 'hann' FFTWINDOW",
            Err(r"FFTWINDOW can only operate on Geo Time Series instances."),
        ),
        (
            r"@NL8 'foo' FFTWINDOW",
            Err(r"FFTWINDOW given an unknown windowing function 'foo'."),
        ),
        (
            r"@S8 'hann' FFTWINDOW",
            Err(r"FFTWINDOW expects numeric Geo Time Series. x{l=v} is not numeric."),
        ),
        (
            r"[ @R8 ] 'foo' FFTWINDOW",
            Err(r"FFTWINDOW given an unknown windowing function 'foo'."),
        ),
    ]);
}
